129	/// Write `body` to `target` atomically: temp file + fsync + rename + dir
130	/// fsync, so a crash either leaves the old file intact or the new one fully
131	/// in place. `dir` must be the directory containing `target`.
132	async fn write_file_atomic_in(dir: &Path, target: &Path, body: &[u8]) -> std::io::Result<()> {
133	    static TMP_COUNTER: AtomicU64 = AtomicU64::new(0);
134	    let tmp = dir.join(format!(
135	        ".tmp-{}-{}",
136	        std::process::id(),
137	        TMP_COUNTER.fetch_add(1, Ordering::Relaxed)
138	    ));
139	
140	    let result = async {
141	        let mut file = tokio::fs::File::create(&tmp).await?;
142	        tokio::io::AsyncWriteExt::write_all(&mut file, body).await?;
143	        file.sync_all().await?;
144	        tokio::fs::rename(&tmp, target).await?;
145	        // Fsync the directory so the rename itself is durable.
146	        let dir_file = tokio::fs::File::open(dir).await?;
147	        dir_file.sync_all().await?;
148	        Ok::<(), std::io::Error>(())
149	    }
150	    .await;
151	
152	    if result.is_err() {
153	        let _ = tokio::fs::remove_file(&tmp).await;
154	    }
155	    result
156	}
