158	/// Write one record atomically, creating the dataset directory on demand.
159	async fn write_file_atomic(
160	    state: &AppState,
161	    name: &str,
162	    key: &str,
163	    body: &[u8],
164	) -> Result<(), Response> {
165	    let dir = ensure_dataset_dir(state, name).await?;
166	    let target = record_path(state, name, key);
167	    write_file_atomic_in(&dir, &target, body)
168	        .await
169	        .map_err(|e| {
170	            tracing_error(&e);
171	            error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal")
172	        })
173	}
