179	async fn get_record(
180	    State(state): State<AppState>,
181	    PathParam((name, key)): PathParam<(String, String)>,
182	) -> Response {
183	    if !valid_identifier(&name) || !valid_identifier(&key) {
184	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
185	    }
186	
187	    // Hold a shared guard for the whole read so a batch commit can never
188	    // expose a half-applied set of files.
189	    let lock = dataset_lock(&name).await;
190	    let _guard = lock.read().await;
191	    let bytes = match tokio::fs::read(record_path(&state, &name, &key)).await {
192	        Ok(b) => b,
193	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
194	            return error_response(StatusCode::NOT_FOUND, "not_found");
195	        }
196	        Err(e) => {
197	            tracing_error(&e);
198	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
199	        }
200	    };
201	    match serde_json::from_slice::<Value>(&bytes) {
202	        Ok(value) => Json(json!({ "key": key, "value": value })).into_response(),
203	        Err(e) => {
204	            eprintln!("corrupt record {name}/{key}: {e}");
205	            error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal")
206	        }
207	    }
208	}
