276	/// Opaque, self-contained continuation token for a paged list. It pins the
277	/// exact filter the page was issued under and the last key returned, so the
278	/// next request resumes strictly after that key in code-point order.
279	/// Keyset positioning (rather than an offset) is what keeps paging stable
280	/// under concurrent writes: records inserted into already-served positions
281	/// are never revisited, and deleted records leave no gap.
282	#[derive(Debug, Serialize, Deserialize, PartialEq, Eq)]
283	struct Cursor {
284	    /// Filter the cursor was minted for; must match the current request.
285	    filter: KeyFilter,
286	    /// Last key of the preceding page; resume strictly after it.
287	    after: String,
288	}
