290	const B64URL_CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
291	
292	/// Encode bytes as unpadded base64url; output contains only
293	/// `[A-Za-z0-9_-]`.
294	fn base64url_encode(input: &[u8]) -> String {
295	    let mut out = String::with_capacity(input.len().div_ceil(3) * 4);
296	    for chunk in input.chunks(3) {
297	        let b0 = chunk[0] as u32;
298	        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
299	        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
300	        let triple = (b0 << 16) | (b1 << 8) | b2;
301	        out.push(B64URL_CHARS[((triple >> 18) & 0x3f) as usize] as char);
302	        out.push(B64URL_CHARS[((triple >> 12) & 0x3f) as usize] as char);
303	        if chunk.len() > 1 {
304	            out.push(B64URL_CHARS[((triple >> 6) & 0x3f) as usize] as char);
305	        }
306	        if chunk.len() > 2 {
307	            out.push(B64URL_CHARS[(triple & 0x3f) as usize] as char);
308	        }
309	    }
310	    out
311	}
312	
313	/// Decode unpadded base64url. Only `[A-Za-z0-9_-]` characters are accepted
314	/// (padding and any other byte are rejected); a dangling final quantum is
315	/// rejected.
316	fn base64url_decode(input: &str) -> Option<Vec<u8>> {
317	    let bytes = input.as_bytes();
318	    if bytes.is_empty() {
319	        return Some(Vec::new());
320	    }
321	    let mut out = Vec::with_capacity(bytes.len() / 4 * 3);
322	    let decode6 = |c: u8| -> Option<u32> {
323	        match c {
324	            b'A'..=b'Z' => Some((c - b'A') as u32),
325	            b'a'..=b'z' => Some((c - b'a' + 26) as u32),
326	            b'0'..=b'9' => Some((c - b'0' + 52) as u32),
327	            b'-' => Some(62),
328	            b'_' => Some(63),
329	            _ => None,
330	        }
331	    };
332	    let (chunks, rem) = bytes.as_chunks::<4>();
333	    for chunk in chunks {
334	        let n0 = decode6(chunk[0])?;
335	        let n1 = decode6(chunk[1])?;
336	        let n2 = decode6(chunk[2])?;
337	        let n3 = decode6(chunk[3])?;
338	        let triple = (n0 << 18) | (n1 << 12) | (n2 << 6) | n3;
339	        out.push((triple >> 16) as u8);
340	        out.push((triple >> 8) as u8);
341	        out.push(triple as u8);
342	    }
343	    // One leftover char carries no byte; two carry one, three carry two.
344	    match rem.len() {
345	        0 => {}
346	        2 => {
347	            let n0 = decode6(rem[0])?;
348	            let n1 = decode6(rem[1])?;
349	            let triple = (n0 << 18) | (n1 << 12);
350	            out.push((triple >> 16) as u8);
351	        }
352	        3 => {
353	            let n0 = decode6(rem[0])?;
354	            let n1 = decode6(rem[1])?;
355	            let n2 = decode6(rem[2])?;
356	            let triple = (n0 << 18) | (n1 << 12) | (n2 << 6);
357	            out.push((triple >> 16) as u8);
358	            out.push((triple >> 8) as u8);
359	        }
360	        _ => return None,
361	    }
362	    Some(out)
363	}
