365	/// Serialize a continuation cursor to its opaque token form.
366	fn encode_cursor(cursor: &Cursor) -> Option<String> {
367	    let json = serde_json::to_vec(cursor).ok()?;
368	    Some(base64url_encode(&json))
369	}
370	
371	/// Parse an opaque continuation token. Any structural, encoding, or
372	/// semantic failure (including an empty `after`) yields an error that the
373	/// caller maps to `invalid_query`.
374	fn decode_cursor(token: &str) -> Result<Cursor, ()> {
375	    let raw = base64url_decode(token).ok_or(())?;
376	    let cursor: Cursor = serde_json::from_slice(&raw).map_err(|_| ())?;
377	    if !valid_identifier(&cursor.after) {
378	        return Err(());
379	    }
380	    // Sanity-check the embedded bounds the same way query parsing does.
381	    if let Some((bound, _)) = &cursor.filter.lower
382	        && !valid_identifier(bound)
383	    {
384	        return Err(());
385	    }
386	    if let Some((bound, _)) = &cursor.filter.upper
387	        && !valid_identifier(bound)
388	    {
389	        return Err(());
390	    }
391	    if let Some(prefix) = &cursor.filter.prefix
392	        && !valid_identifier(prefix)
393	    {
394	        return Err(());
395	    }
396	    Ok(cursor)
397	}
