399	fn hex_val(b: u8) -> Option<u8> {
400	    match b {
401	        b'0'..=b'9' => Some(b - b'0'),
402	        b'a'..=b'f' => Some(b - b'a' + 10),
403	        b'A'..=b'F' => Some(b - b'A' + 10),
404	        _ => None,
405	    }
406	}
