408	/// Decode one query-string component: `%XX` escapes and `+` as space.
409	fn percent_decode(s: &str) -> Result<String, ()> {
410	    let bytes = s.as_bytes();
411	    let mut out = Vec::with_capacity(bytes.len());
412	    let mut i = 0;
413	    while i < bytes.len() {
414	        match bytes[i] {
415	            b'%' => {
416	                if i + 2 >= bytes.len() {
417	                    return Err(());
418	                }
419	                let hi = hex_val(bytes[i + 1]).ok_or(())?;
420	                let lo = hex_val(bytes[i + 2]).ok_or(())?;
421	                out.push(hi << 4 | lo);
422	                i += 3;
423	            }
424	            b'+' => {
425	                out.push(b' ');
426	                i += 1;
427	            }
428	            b => {
429	                out.push(b);
430	                i += 1;
431	            }
432	        }
433	    }
434	    String::from_utf8(out).map_err(|_| ())
435	}
