437	/// Maximum page size accepted by the list endpoint.
438	const MAX_LIMIT: usize = 1000;
439	
440	/// Parsed list query: the key filter plus optional keyset pagination.
441	struct ListQuery {
442	    filter: KeyFilter,
443	    limit: Option<usize>,
444	    /// Raw continuation token, already validated as non-empty and
445	    /// `[A-Za-z0-9_-]`-only; decoded later against the current filter.
446	    cursor: Option<String>,
447	}
448	
449	/// Parse the query string into a key filter and pagination parameters. Any
450	/// parameter outside the documented set (`prefix`, `gte`, `gt`, `lte`,
451	/// `lt`, `limit`, `cursor`), duplicates, conflicting bounds, values that are
452	/// not valid key fragments (non-empty, `[A-Za-z0-9_-]`), a `limit` outside
453	/// 1..=1000, or an empty/illegal `cursor` are rejected.
454	fn parse_list_query(query: &str) -> Result<ListQuery, ()> {
455	    let mut filter = KeyFilter::default();
456	    if query.is_empty() {
457	        return Ok(ListQuery {
458	            filter,
459	            limit: None,
460	            cursor: None,
461	        });
462	    }
463	    let mut gte: Option<String> = None;
464	    let mut gt: Option<String> = None;
465	    let mut lte: Option<String> = None;
466	    let mut lt: Option<String> = None;
467	    let mut limit: Option<usize> = None;
468	    let mut cursor: Option<String> = None;
469	
470	    for pair in query.split('&') {
471	        let (raw_name, raw_value) = pair.split_once('=').ok_or(())?;
472	        let name = percent_decode(raw_name)?;
473	        let value = percent_decode(raw_value)?;
474	        match name.as_str() {
475	            "limit" => {
476	                // Strict decimal integer: digits only, no sign or other
477	                // characters; range-checked to 1..=1000 below.
478	                if value.is_empty() || !value.bytes().all(|b| b.is_ascii_digit()) {
479	                    return Err(());
480	                }
481	                let parsed: usize = value.parse().map_err(|_| ())?;
482	                if !(1..=MAX_LIMIT).contains(&parsed) {
483	                    return Err(());
484	                }
485	                if limit.is_some() {
486	                    return Err(());
487	                }
488	                limit = Some(parsed);
489	            }
490	            "cursor" => {
491	                // Non-empty, opaque, charset-restricted. Full structural
492	                // validation happens once the current filter is known.
493	                if value.is_empty()
494	                    || !value
495	                        .bytes()
496	                        .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
497	                {
498	                    return Err(());
499	                }
500	                if cursor.is_some() {
501	                    return Err(());
502	                }
503	                cursor = Some(value);
504	            }
505	            "prefix" | "gte" | "gt" | "lte" | "lt" => {
506	                if !valid_identifier(&value) {
507	                    return Err(());
508	                }
509	                let slot = match name.as_str() {
510	                    "prefix" => &mut filter.prefix,
511	                    "gte" => &mut gte,
512	                    "gt" => &mut gt,
513	                    "lte" => &mut lte,
514	                    "lt" => &mut lt,
515	                    _ => unreachable!(),
516	                };
517	                if slot.is_some() {
518	                    return Err(());
519	                }
520	                *slot = Some(value);
521	            }
522	            _ => return Err(()),
523	        }
524	    }
525	
526	    if filter.prefix.is_some() && (gte.is_some() || gt.is_some() || lte.is_some() || lt.is_some()) {
527	        return Err(());
528	    }
529	    if gte.is_some() && gt.is_some() {
530	        return Err(());
531	    }
532	    if lte.is_some() && lt.is_some() {
533	        return Err(());
534	    }
535	    filter.lower = gte.map(|b| (b, true)).or_else(|| gt.map(|b| (b, false)));
536	    filter.upper = lte.map(|b| (b, true)).or_else(|| lt.map(|b| (b, false)));
537	    Ok(ListQuery {
538	        filter,
539	        limit,
540	        cursor,
541	    })
542	}
