544	async fn list_records(
545	    State(state): State<AppState>,
546	    PathParam(name): PathParam<String>,
547	    uri: Uri,
548	) -> Response {
549	    if !valid_identifier(&name) {
550	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
551	    }
552	    let query = match parse_list_query(uri.query().unwrap_or("")) {
553	        Ok(query) => query,
554	        Err(()) => return error_response(StatusCode::BAD_REQUEST, "invalid_query"),
555	    };
556	
557	    // A continuation token is accepted only when it decodes and pins the
558	    // exact filter of this request; it then marks the resume position.
559	    let after: Option<String> = match query.cursor.as_deref() {
560	        None => None,
561	        Some(token) => match decode_cursor(token) {
562	            Ok(cursor) if cursor.filter == query.filter => Some(cursor.after),
563	            // Corrupt token, unparseable payload, or filter mismatch.
564	            _ => return error_response(StatusCode::BAD_REQUEST, "invalid_query"),
565	        },
566	    };
567	
568	    // Shared guard across the whole scan: commits rename files one by one,
569	    // so without this a list could interleave a batch in progress.
570	    let lock = dataset_lock(&name).await;
571	    let _guard = lock.read().await;
572	    let dir = state.data_dir.join(&name);
573	    let mut entries = match tokio::fs::read_dir(&dir).await {
574	        Ok(entries) => entries,
575	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
576	            return error_response(StatusCode::NOT_FOUND, "not_found");
577	        }
578	        Err(e) => {
579	            tracing_error(&e);
580	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
581	        }
582	    };
583	
584	    let mut records: Vec<(String, Value, SystemTime)> = Vec::new();
585	    loop {
586	        let entry = match entries.next_entry().await {
587	            Ok(Some(entry)) => entry,
588	            Ok(None) => break,
589	            Err(e) => {
590	                tracing_error(&e);
591	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
592	            }
593	        };
594	        let file_name = entry.file_name();
595	        let Some(file_name) = file_name.to_str() else {
596	            continue;
597	        };
598	        let Some(key) = file_name.strip_suffix(".json") else {
599	            continue;
600	        };
601	        // Filter on the key alone, before reading: records outside the hit
602	        // set are excluded even if their file is corrupt or unreadable.
603	        if !query.filter.matches(key) {
604	            continue;
605	        }
606	
607	        let result = async {
608	            let bytes = tokio::fs::read(entry.path()).await?;
609	            let modified = entry.metadata().await?.modified()?;
610	            Ok::<(Vec<u8>, SystemTime), std::io::Error>((bytes, modified))
611	        }
612	        .await;
613	        let (bytes, modified) = match result {
614	            Ok(ok) => ok,
615	            Err(e) => {
616	                tracing_error(&e);
617	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
618	            }
619	        };
620	        let value: Value = match serde_json::from_slice(&bytes) {
621	            Ok(value) => value,
622	            Err(e) => {
623	                eprintln!("corrupt record {name}/{key}: {e}");
624	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
625	            }
626	        };
627	        records.push((key.to_owned(), value, modified));
628	    }
629	
630	    // Byte-wise order on UTF-8 is Unicode code-point order.
631	    records.sort_by(|a, b| a.0.cmp(&b.0));
632	
633	    // Keyset resume: drop everything up to and including `after`. Position
634	    // is derived from the key order rather than an offset, so records
635	    // inserted behind the cursor are simply never revisited and deleted
636	    // positions leave no gap.
637	    let mut start = 0usize;
638	    if let Some(after) = &after {
639	        // A genuine cursor always names a record the preceding page
640	        // returned: it must lie inside the current filter's hit set, exist
641	        // exactly in it, and have a non-empty tail (nextCursor is only ever
642	        // minted while more records remain). Anything else is a forged,
643	        // corrupt, or out-of-bounds token.
644	        if !query.filter.matches(after) {
645	            return error_response(StatusCode::BAD_REQUEST, "invalid_query");
646	        }
647	        // First index whose key is strictly greater than `after`.
648	        start = records.partition_point(|(key, _, _)| key.as_str() <= after.as_str());
649	        let points_at_real_record = start > 0
650	            && records
651	                .get(start - 1)
652	                .is_some_and(|(key, _, _)| key == after);
653	        if !points_at_real_record || start >= records.len() {
654	            return error_response(StatusCode::BAD_REQUEST, "invalid_query");
655	        }
656	    }
657	
658	    let total = records.len();
659	    let end = match query.limit {
660	        Some(limit) => (start + limit).min(total),
661	        None => total,
662	    };
663	
664	    let mut next_cursor: Option<String> = None;
665	    if let Some(limit) = query.limit
666	        && start + limit < total
667	    {
668	        let last_key = &records[end - 1].0;
669	        // A cursor that cannot be minted is an internal failure, not a
670	        // client error: fail the whole request rather than return a
671	        // unpageable slice.
672	        let token = match encode_cursor(&Cursor {
673	            filter: query.filter.clone(),
674	            after: last_key.clone(),
675	        }) {
676	            Some(token) => token,
677	            None => return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal"),
678	        };
679	        next_cursor = Some(token);
680	    }
681	
682	    let page: Vec<Value> = records[start..end]
683	        .iter()
684	        .map(|(key, value, modified)| {
685	            json!({
686	                "key": key,
687	                "value": value,
688	                "updatedAt": format_rfc3339_utc(*modified),
689	            })
690	        })
691	        .collect();
692	
693	    // Legacy response shape (no limit, no cursor) carries exactly the two
694	    // fields; paged responses add nextCursor only while a tail remains.
695	    let mut body = json!({ "name": name, "records": page });
696	    if let Some(token) = next_cursor {
697	        body["nextCursor"] = Value::String(token);
698	    }
699	    Json(body).into_response()
700	}
