702	// ---------------------------------------------------------------------------
703	// Batch writes
704	//
705	// A batch is staged in a sibling directory of the dataset before any record
706	// file is touched:
707	//
708	//   <data_dir>/.<name>.batch-<pid>-<n>/
709	//     MANIFEST          - JSON: dataset name, batch keys, per-key "existed"
710	//                         flag, and the batch commit time; durable before
711	//                         COMMIT so recovery never has to infer key state
712	//                         from partially moved directories
713	//     COMMIT            - present once the whole batch is durably staged
714	//     ABORT             - present once a rollback has been decided
715	//     new/<key>.json    - new payload, staged via temp file + fsync + rename
716	//     old/<key>.json    - hardlink to the pre-request file (existing keys)
717	//
718	// Records are switched into the dataset only after COMMIT is durable, and
719	// the dataset directory is fsynced once all renames are done. A crash before
720	// COMMIT leaves the dataset untouched; a crash afterwards is completed at
721	// startup (re-apply) or, if ABORT exists, rolled back. Old payloads are
722	// captured as hardlinks, so rolling back restores both content and inode
723	// metadata (notably updatedAt). MANIFEST records whether each key existed
724	// beforehand, making both resume paths idempotent regardless of where a
725	// previous attempt stopped.
726	// ---------------------------------------------------------------------------
727	
728	const COMMIT_MARKER: &str = "COMMIT";
729	const ABORT_MARKER: &str = "ABORT";
730	const MANIFEST_FILE: &str = "MANIFEST";
731	
732	/// Why a batch request was rejected.
733	#[derive(Clone, Copy, PartialEq, Eq)]
734	enum BatchError {
735	    /// Malformed JSON envelope or entries.
736	    InvalidJson,
737	    /// An entry key (already structurally present) violates identifier rules.
738	    InvalidIdentifier,
739	}
740	
741	/// Validate and parse a batch request body into `(key, value)` pairs.
742	fn parse_batch_records(body: &[u8]) -> Result<Vec<(String, Value)>, BatchError> {
743	    if body.is_empty() {
744	        return Err(BatchError::InvalidJson);
745	    }
746	    let parsed: Value = serde_json::from_slice(body).map_err(|_| BatchError::InvalidJson)?;
747	    let Some(obj) = parsed.as_object() else {
748	        return Err(BatchError::InvalidJson);
749	    };
750	    // Missing `records`, or a non-array value, is invalid_json.
751	    let Some(arr) = obj.get("records").and_then(|v| v.as_array()) else {
752	        return Err(BatchError::InvalidJson);
753	    };
754	
755	    let mut entries: Vec<(String, Value)> = Vec::with_capacity(arr.len());
756	    for item in arr {
757	        // Every entry must be an object with a string `key` and a present
758	        // `value` (which may itself be null).
759	        let Some(item) = item.as_object() else {
760	            return Err(BatchError::InvalidJson);
761	        };
762	        let Some(key) = item.get("key").and_then(|k| k.as_str()) else {
763	            return Err(BatchError::InvalidJson);
764	        };
765	        let Some(value) = item.get("value") else {
766	            return Err(BatchError::InvalidJson);
767	        };
768	        entries.push((key.to_owned(), value.clone()));
769	    }
770	
771	    // A key that violates the identifier charset is invalid_identifier.
772	    if entries.iter().any(|(key, _)| !valid_identifier(key)) {
773	        return Err(BatchError::InvalidIdentifier);
774	    }
775	
776	    // Duplicate keys within one batch are invalid_json.
777	    let mut seen = HashSet::with_capacity(entries.len());
778	    for (key, _) in &entries {
779	        if !seen.insert(key.as_str()) {
780	            return Err(BatchError::InvalidJson);
781	        }
782	    }
783	    Ok(entries)
784	}
785	
786	async fn fsync_dir(dir: &Path) -> std::io::Result<()> {
787	    tokio::fs::File::open(dir).await?.sync_all().await
788	}
