790	/// Set a file's mtime and fsync it off the async runtime's worker threads
791	/// (set_modified/fsync are blocking syscalls).
792	async fn stamp_mtime_durable(path: PathBuf, at: SystemTime) -> std::io::Result<()> {
793	    tokio::task::spawn_blocking(move || {
794	        let file = std::fs::File::open(&path)?;
795	        file.set_modified(at)?;
796	        file.sync_all()
797	    })
798	    .await
799	    .map_err(std::io::Error::other)??;
800	    Ok(())
801	}
