803	/// Staging directory for a batch: a sibling of the dataset directory.
804	fn staging_dir(state: &AppState, name: &str) -> PathBuf {
805	    state.data_dir.join(format!(
806	        ".{name}.batch-{}-{}",
807	        std::process::id(),
808	        BATCH_COUNTER.fetch_add(1, Ordering::Relaxed)
809	    ))
810	}
