812	/// One batch key as recorded in MANIFEST.
813	#[derive(serde::Serialize, serde::Deserialize)]
814	struct ManifestKey {
815	    key: String,
816	    /// Whether the record existed (and was snapshotted into `old/`) before
817	    /// the batch.
818	    existed: bool,
819	}
820	
821	/// On-disk MANIFEST describing a staged batch.
822	#[derive(serde::Serialize, serde::Deserialize)]
823	struct Manifest {
824	    name: String,
825	    commit_at_ms: u128,
826	    keys: Vec<ManifestKey>,
827	}
828	
829	impl Manifest {
830	    fn commit_time(&self) -> SystemTime {
831	        SystemTime::UNIX_EPOCH + std::time::Duration::from_millis(self.commit_at_ms as u64)
832	    }
833	}
834	
835	/// A staged batch ready to be switched into place.
836	struct StagedBatch {
837	    dir: PathBuf,
838	    manifest: Manifest,
839	}
840	
841	fn now_epoch_ms() -> u128 {
842	    SystemTime::now()
843	        .duration_since(SystemTime::UNIX_EPOCH)
844	        .map(|d| d.as_millis())
845	        .unwrap_or(0)
846	}
