848	/// Snapshot existing records and stage every new payload, write MANIFEST and
849	/// then the durable COMMIT marker. No dataset record is modified until this
850	/// returns. On error the staging directory is removed; the dataset is left
851	/// untouched.
852	async fn stage_batch(
853	    state: &AppState,
854	    name: &str,
855	    entries: &[(String, Value)],
856	) -> std::io::Result<StagedBatch> {
857	    let dir = staging_dir(state, name);
858	    let new_dir = dir.join("new");
859	    let old_dir = dir.join("old");
860	    let setup = async {
861	        tokio::fs::create_dir_all(&new_dir).await?;
862	        tokio::fs::create_dir_all(&old_dir).await?;
863	        // Make the staging directory itself durable.
864	        fsync_dir(state.data_dir.as_ref()).await?;
865	        Ok::<(), std::io::Error>(())
866	    }
867	    .await;
868	    if let Err(e) = setup {
869	        let _ = tokio::fs::remove_dir_all(&dir).await;
870	        return Err(e);
871	    }
872	
873	    let result = async {
874	        let mut manifest_keys = Vec::with_capacity(entries.len());
875	        for (key, value) in entries {
876	            // Snapshot the pre-request file, if any. A hardlink keeps the
877	            // exact inode (content and mtime) alive for rollback.
878	            let target = record_path(state, name, key);
879	            let snapshot = old_dir.join(format!("{key}.json"));
880	            let existed = match tokio::fs::hard_link(&target, &snapshot).await {
881	                Ok(()) => true,
882	                Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
883	                Err(e) => return Err(e),
884	            };
885	            manifest_keys.push(ManifestKey {
886	                key: key.clone(),
887	                existed,
888	            });
889	
890	            let body = serde_json::to_vec(value).map_err(std::io::Error::other)?;
891	            write_file_atomic_in(&new_dir, &new_dir.join(format!("{key}.json")), &body).await?;
892	        }
893	        // Persist the snapshot hardlinks' directory entries; recovery may
894	        // need them to undo a committed batch.
895	        fsync_dir(&old_dir).await?;
896	
897	        // The manifest (with the batch's commit timestamp) must be durable
898	        // before COMMIT: recovery relies on it to resume or undo the batch.
899	        let manifest = Manifest {
900	            name: name.to_owned(),
901	            commit_at_ms: now_epoch_ms(),
902	            keys: manifest_keys,
903	        };
904	        let manifest_body = serde_json::to_vec_pretty(&manifest).map_err(std::io::Error::other)?;
905	        write_file_atomic_in(&dir, &dir.join(MANIFEST_FILE), &manifest_body).await?;
906	
907	        // Commit point: once this rename + fsync is durable, the batch must
908	        // either apply fully on every future startup or be explicitly
909	        // aborted.
910	        write_file_atomic_in(&dir, &dir.join(COMMIT_MARKER), b"committed\n").await?;
911	        Ok::<Manifest, std::io::Error>(manifest)
912	    }
913	    .await;
914	
915	    match result {
916	        Ok(manifest) => Ok(StagedBatch { dir, manifest }),
917	        Err(e) => {
918	            let _ = tokio::fs::remove_dir_all(&dir).await;
919	            Err(e)
920	        }
921	    }
922	}
923	
924	/// Rename every staged payload into the dataset, stamp each record's mtime
925	/// with the batch commit time (updatedAt is the write-completion moment),
926	/// fsync, then read each record back and verify the stored value. Returns
927	/// the verified `(key, value, modified)` rows.
928	async fn switch_batch(
929	    state: &AppState,
930	    name: &str,
931	    staged: &StagedBatch,
932	    entries: &[(String, Value)],
933	) -> std::io::Result<Vec<(String, Value, SystemTime)>> {
934	    let dir = ensure_dataset_dir_raw(state, name).await?;
935	    let new_dir = staged.dir.join("new");
936	    let commit_time = staged.manifest.commit_time();
937	
938	    for item in &staged.manifest.keys {
939	        let from = new_dir.join(format!("{}.json", item.key));
940	        let to = record_path(state, name, &item.key);
941	        // rename(2) atomically replaces the destination on Unix.
942	        tokio::fs::rename(&from, &to).await?;
943	    }
944	    // One fsync after all renames makes the whole switch durable together.
945	    fsync_dir(&dir).await?;
946	    // The dataset directory may itself be new; persist its parent entry too.
947	    fsync_dir(state.data_dir.as_ref()).await?;
948	
949	    let expected: HashMap<&str, &Value> = entries.iter().map(|(k, v)| (k.as_str(), v)).collect();
950	    let mut verified = Vec::with_capacity(staged.manifest.keys.len());
951	    for item in &staged.manifest.keys {
952	        let key = item.key.as_str();
953	        let path = record_path(state, name, key);
954	
955	        // Rename preserves the staged file's mtime; stamp it with the batch
956	        // commit time so updatedAt reflects the write completion.
957	        stamp_mtime_durable(path.clone(), commit_time).await?;
958	
959	        let bytes = tokio::fs::read(&path).await?;
960	        let modified = tokio::fs::metadata(&path).await?.modified()?;
961	        let stored: Value = serde_json::from_slice(&bytes).map_err(std::io::Error::other)?;
962	        if Some(&stored) != expected.get(key).copied() {
963	            return Err(std::io::Error::other(format!(
964	                "post-commit verification mismatch for {name}/{key}"
965	            )));
966	        }
967	        verified.push((item.key.clone(), stored, modified));
968	    }
969	    Ok(verified)
970	}
