972	async fn ensure_dataset_dir_raw(state: &AppState, name: &str) -> std::io::Result<PathBuf> {
973	    let dir = state.data_dir.join(name);
974	    tokio::fs::create_dir_all(&dir).await?;
975	    Ok(dir)
976	}
