978	/// Durably abandon a staged batch: mark ABORT, restore every snapshot and
979	/// delete newly created records, fsync the dataset, then discard the
980	/// journal. Idempotent, so it can be re-driven by crash recovery.
981	async fn abort_batch(state: &AppState, name: &str, staged: &StagedBatch) -> std::io::Result<()> {
982	    // The ABORT marker makes the rollback decision durable before any
983	    // dataset file is touched.
984	    let abort_path = staged.dir.join(ABORT_MARKER);
985	    if tokio::fs::try_exists(&abort_path).await.unwrap_or(false) {
986	        // Already decided; nothing to write.
987	    } else {
988	        write_file_atomic_in(&staged.dir, &abort_path, b"aborted\n").await?;
989	    }
990	
991	    let old_dir = staged.dir.join("old");
992	    let mut first_err: Option<std::io::Error> = None;
993	    for item in &staged.manifest.keys {
994	        let target = record_path(state, name, &item.key);
995	        if item.existed {
996	            let snapshot = old_dir.join(format!("{}.json", item.key));
997	            // Restore the old inode (content + mtime). A missing snapshot
998	            // means a previous attempt already restored it.
999	            match tokio::fs::rename(&snapshot, &target).await {
1000	                Ok(()) => {}
1001	                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
1002	                Err(e) if first_err.is_none() => first_err = Some(e),
1003	                Err(_) => {}
1004	            }
1005	        } else {
1006	            // Newly created by the batch; remove it. NotFound means an
1007	            // earlier attempt already removed it.
1008	            match tokio::fs::remove_file(&target).await {
1009	                Ok(()) => {}
1010	                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
1011	                Err(e) if first_err.is_none() => first_err = Some(e),
1012	                Err(_) => {}
1013	            }
1014	        }
1015	    }
1016	    if let Err(e) = fsync_dir(&state.data_dir.join(name)).await
1017	        && first_err.is_none()
1018	    {
1019	        first_err = Some(e);
1020	    }
1021	    if let Err(e) = fsync_dir(state.data_dir.as_ref()).await
1022	        && first_err.is_none()
1023	    {
1024	        first_err = Some(e);
1025	    }
1026	
1027	    finish_batch_cleanup(&staged.dir, &abort_path).await;
1028	
1029	    match first_err {
1030	        Some(e) => Err(e),
1031	        None => Ok(()),
1032	    }
1033	}
1034	
1035	/// Retire the journal markers durably, then remove the staging directory.
1036	/// Shared by the commit and abort paths.
1037	async fn finish_batch_cleanup(staging: &Path, abort_path: &Path) {
1038	    let _ = tokio::fs::remove_file(staging.join(COMMIT_MARKER)).await;
1039	    let _ = tokio::fs::remove_file(abort_path).await;
1040	    let _ = tokio::fs::remove_file(staging.join(MANIFEST_FILE)).await;
1041	    let _ = fsync_dir(staging).await;
1042	    let _ = tokio::fs::remove_dir_all(staging).await;
1043	}
1044	
1045	/// Remove the journal of a successfully applied batch. Errors here are not
1046	/// fatal to the request (the batch is already durable); startup recovery
1047	/// sweeps anything left behind.
1048	async fn discard_batch(staged: &StagedBatch) {
1049	    finish_batch_cleanup(&staged.dir, &staged.dir.join(ABORT_MARKER)).await;
1050	}
