1052	async fn put_records(
1053	    State(state): State<AppState>,
1054	    PathParam(name): PathParam<String>,
1055	    body: Bytes,
1056	) -> Response {
1057	    if !valid_identifier(&name) {
1058	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
1059	    }
1060	    let entries = match parse_batch_records(&body) {
1061	        Ok(entries) => entries,
1062	        Err(BatchError::InvalidIdentifier) => {
1063	            return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
1064	        }
1065	        Err(BatchError::InvalidJson) => {
1066	            return error_response(StatusCode::BAD_REQUEST, "invalid_json");
1067	        }
1068	    };
1069	
1070	    // An empty batch is a legal no-op: 200 with an empty records array.
1071	    if entries.is_empty() {
1072	        return Json(json!({ "name": name, "records": [] })).into_response();
1073	    }
1074	
1075	    // Exclusive with every other read and write of this dataset for the
1076	    // duration of the commit.
1077	    let lock = dataset_lock(&name).await;
1078	    let _guard = lock.write().await;
1079	
1080	    let staged = match stage_batch(&state, &name, &entries).await {
1081	        Ok(staged) => staged,
1082	        Err(e) => {
1083	            tracing_error(&e);
1084	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
1085	        }
1086	    };
1087	
1088	    let verified = match switch_batch(&state, &name, &staged, &entries).await {
1089	        Ok(rows) => rows,
1090	        Err(e) => {
1091	            tracing_error(&e);
1092	            // Restore the exact pre-request dataset; if even that fails the
1093	            // on-disk journal is re-driven (towards abort) at next startup.
1094	            if let Err(rollback_err) = abort_batch(&state, &name, &staged).await {
1095	                tracing_error(&rollback_err);
1096	            }
1097	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
1098	        }
1099	    };
1100	
1101	    discard_batch(&staged).await;
1102	
1103	    // Byte-wise order on UTF-8 is Unicode code-point order.
1104	    let mut verified = verified;
1105	    verified.sort_by(|a, b| a.0.cmp(&b.0));
1106	    let records: Vec<Value> = verified
1107	        .into_iter()
1108	        .map(|(key, value, modified)| {
1109	            json!({
1110	                "key": key,
1111	                "value": value,
1112	                "updatedAt": format_rfc3339_utc(modified),
1113	            })
1114	        })
1115	        .collect();
1116	    Json(json!({ "name": name, "records": records })).into_response()
1117	}
1118	
1119	/// Finish or undo one staging directory found at startup. MANIFEST drives
1120	/// every decision, so resume work is idempotent no matter how far a prior
1121	/// attempt (live or recovery) got.
1122	async fn recover_one_batch(data_dir: &Path, staging: &Path) {
1123	    let file_name = match staging.file_name().and_then(|n| n.to_str()) {
1124	        Some(n) => n.to_owned(),
1125	        None => {
1126	            let _ = tokio::fs::remove_dir_all(staging).await;
1127	            return;
1128	        }
1129	    };
1130	    // Layout: .<name>.batch-<pid>-<n>, identifiers are [A-Za-z0-9_-].
1131	    let marked = file_name.strip_prefix('.').unwrap_or(&file_name);
1132	    let Some((_dir_name, _)) = marked.split_once(".batch-") else {
1133	        let _ = tokio::fs::remove_dir_all(staging).await;
1134	        return;
1135	    };
1136	
1137	    // Crashed before/while writing MANIFEST or COMMIT: no record was ever
1138	    // renamed, so the dataset is untouched and the journal can be discarded.
1139	    let manifest_path = staging.join(MANIFEST_FILE);
1140	    let commit_path = staging.join(COMMIT_MARKER);
1141	    let abort_path = staging.join(ABORT_MARKER);
1142	    let has_manifest = tokio::fs::try_exists(&manifest_path).await.unwrap_or(false);
1143	    let has_commit = tokio::fs::try_exists(&commit_path).await.unwrap_or(false);
1144	    if !has_manifest || !has_commit {
1145	        let _ = tokio::fs::remove_dir_all(staging).await;
1146	        return;
1147	    }
1148	
1149	    let manifest_bytes = match tokio::fs::read(&manifest_path).await {
1150	        Ok(b) => b,
1151	        // A torn manifest means the batch never reached its commit point;
1152	        // the dataset was not modified.
1153	        Err(_) => {
1154	            let _ = tokio::fs::remove_dir_all(staging).await;
1155	            return;
1156	        }
1157	    };
1158	    let manifest: Manifest = match serde_json::from_slice(&manifest_bytes) {
1159	        Ok(m) => m,
1160	        Err(_) => {
1161	            let _ = tokio::fs::remove_dir_all(staging).await;
1162	            return;
1163	        }
1164	    };
