1166	    let dataset_dir = data_dir.join(&name);
1167	    let has_abort = tokio::fs::try_exists(&abort_path).await.unwrap_or(false);
1168	    let new_dir = staging.join("new");
1169	    let old_dir = staging.join("old");
1170	
1171	    if has_abort {
1172	        // Resume an interrupted rollback.
1173	        let _ = tokio::fs::create_dir_all(&dataset_dir).await;
1174	        for item in &manifest.keys {
