1210	        let _ = fsync_dir(&dataset_dir).await;
1211	        let _ = fsync_dir(data_dir).await;
1212	    }
1213	
1214	    // The dataset is now in a complete state; retire the journal.
1215	    finish_batch_cleanup(staging, &abort_path).await;
1216	}
