1218	/// Sweep staging directories left by processes that died mid-batch. Runs
1219	/// once before the server starts accepting requests.
1220	async fn recover_pending_batches(state: &AppState) {
1221	    let mut entries = match tokio::fs::read_dir(state.data_dir.as_ref()).await {
1222	        Ok(entries) => entries,
1223	        // A fresh deployment has no data directory yet.
1224	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return,
